public:
    std::vector<std::vector<int>> closestNodes(TreeNode* root, std::vector<int>& queries) {
        std::vector<int> vals;
        inorder(root, vals);
        int n = vals.size();
        std::vector<std::vector<int>> ans;
        for (int q : queries) {
            auto it = std::upper_bound(vals.begin(), vals.end(), q);
            int idx = it - vals.begin();
            int mini = (idx > 0) ? vals[idx - 1] : -1;
            int maxi = -1;
            if (idx > 0 && vals[idx - 1] == q) maxi = q;
            else if (idx < n) maxi = vals[idx];
            ans.push_back({mini, maxi});
        }
        return ans;
    }
};

class Solution {
    public java.util.List<java.util.List<Integer>> closestNodes(TreeNode root, java.util.List<Integer> queries) {
        java.util.List<Integer> vals = new java.util.ArrayList<>();
        inorder(root, vals);
        java.util.List<java.util.List<Integer>> ans = new java.util.ArrayList<>();
        int n = vals.size();
        for (int q : queries) {
            int idx = java.util.Collections.binarySearch(vals, q);
            if (idx >= 0) {
                ans.add(java.util.Arrays.asList(q, q));
            } else {
                int ins = -idx - 1;
                int mini = (ins > 0) ? vals.get(ins - 1) : -1;
                int maxi = (ins < n) ? vals.get(ins) : -1;
                ans.add(java.util.Arrays.asList(mini, maxi));
            }
        }
        return ans;
    }
    private void inorder(TreeNode node, java.util.List<Integer> vals) {
        if (node == null) return;
        inorder(node.left, vals);
        vals.add(node.val);
        inorder(node.right, vals);
    }
}

var closestNodes = function(root, queries) {
    const vals = [];
    const inorder = (node) => {
        if (!node) return;
        inorder(node.left);
        vals.push(node.val);
        inorder(node.right);
    };
    inorder(root);
    const n = vals.length;
    const ans = [];
    for (const q of queries) {
        let l = 0, r = n;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (vals[mid] <= q) l = mid + 1;
            else r = mid;
        }
        const idx = l;
        const mini = idx > 0 ? vals[idx - 1] : -1;
        let maxi = -1;
        if (idx > 0 && vals[idx - 1] === q) maxi = q;
        else if (idx < n) maxi = vals[idx];
        ans.push([mini, maxi]);
    }
    return ans;
};
